    10→
    11→// ────────────────────────────────────────────────────────────────
    12→// Voice Agent Best Practices Checklist
    13→// Derived from GPT 4.1 voice agent prompt engineering framework
    14→// ────────────────────────────────────────────────────────────────
    15→
    16→interface Issue {
    17→  category: string;
    18→  rule: string;
    19→  severity: "critical" | "warning" | "info";
    20→  evidence: string;
    21→  call_id: string;
    22→  suggestion: string;
    23→}
    24→
    25→interface TranscriptUtterance {
    26→  role: string;
    27→  content: string;
    28→  words?: Array<{ word: string; start: number; end: number }>;
    29→}
    30→
    31→function analyzeTranscript(
    32→  callId: string,
    33→  transcript: string,
    34→  utterances: TranscriptUtterance[] | null
    35→): Issue[] {
    36→  const issues: Issue[] = [];
    37→  const agentLines = utterances
    38→    ? utterances.filter((u) => u.role === "agent").map((u) => u.content)
    39→    : extractAgentLines(transcript);
    40→  const userLines = utterances
    41→    ? utterances.filter((u) => u.role === "user").map((u) => u.content)
    42→    : extractUserLines(transcript);
    43→
    44→  // ── 1. MULTIPLE QUESTIONS IN ONE TURN ─────────────────────
    45→  for (const line of agentLines) {
    46→    const questionMarks = (line.match(/\?/g) || []).length;
    47→    if (questionMarks >= 2) {
    48→      issues.push({
    49→        category: "Communication Flow",
    50→        rule: "Ask only one question at a time",
    51→        severity: "critical",
    52→        evidence: truncate(line, 200),
    53→        call_id: callId,
    54→        suggestion:
    55→          "Split into separate turns. Ask one question, wait for response, then ask the next.",
    56→      });
    57→    }
    58→  }
    59→
    60→  // ── 2. BUNDLED REQUESTS ───────────────────────────────────
    61→  const bundlePatterns = [
    62→    /(?:email|phone|number|address|name).+(?:and|&).+(?:email|phone|number|address|name)/i,
    63→    /what(?:'s| is) your .+ and .+\?/i,
    64→    /can you (?:give|provide|share) (?:me )?your .+ and .+/i,
    65→  ];
    66→  for (const line of agentLines) {
    67→    for (const pattern of bundlePatterns) {
    68→      if (pattern.test(line)) {
    69→        issues.push({
    70→          category: "Communication Flow",
    71→          rule: "Never bundle multiple requests",
    72→          severity: "critical",
    73→          evidence: truncate(line, 200),
    74→          call_id: callId,
    75→          suggestion:
    76→            'Ask for each piece of information separately. E.g., "What\'s your email?" then wait, then "And your phone number?"',
    77→        });
    78→        break;
    79→      }
    80→    }
    81→  }
    82→
    83→  // ── 3. REPEATED ENTHUSIASTIC RESPONSES ────────────────────
    84→  const enthusiasticWords = [
    85→    "great",
    86→    "perfect",
    87→    "awesome",
    88→    "wonderful",
    89→    "fantastic",
    90→    "excellent",
    91→    "amazing",
    92→    "sounds good",
    93→  ];
    94→  const recentEnthusiastic: string[] = [];
    95→  for (const line of agentLines) {
    96→    const lower = line.toLowerCase();
    97→    for (const word of enthusiasticWords) {
    98→      if (lower.includes(word)) {
    99→        if (recentEnthusiastic.length >= 2 && recentEnthusiastic.includes(word)) {
   100→          issues.push({
   101→            category: "Communication Flow",
   102→            rule: "Vary enthusiastic responses - avoid repetition",
   103→            severity: "warning",
   104→            evidence: `Repeated "${word}" - used ${recentEnthusiastic.filter((w) => w === word).length + 1} times in recent exchanges`,
   105→            call_id: callId,
   106→            suggestion:
   107→              'Rotate between "Great!", "Sounds good", "Perfect", "Got it", etc.',
   108→          });
   109→        }
   110→        recentEnthusiastic.push(word);
   111→        if (recentEnthusiastic.length > 6) recentEnthusiastic.shift();
   112→        break;
   113→      }
   114→    }
   115→  }
   116→
   117→  // ── 4. EM DASH USAGE ──────────────────────────────────────
   118→  for (const line of agentLines) {
   119→    if (line.includes("\u2014") || line.includes("\u2013")) {
   120→      issues.push({
   121→        category: "Technical Precision",
   122→        rule: 'Never use em dash (\u2014), always use hyphen (-)',
   123→        severity: "warning",
   124→        evidence: truncate(line, 200),
   125→        call_id: callId,
   126→        suggestion: "Replace all em dashes (\u2014) and en dashes (\u2013) with regular hyphens (-).",
   127→      });
   128→    }
   129→  }
   130→
   131→  // ── 5. SYMBOLS NOT WRITTEN AS WORDS ───────────────────────
   132→  const symbolPatterns = [
   133→    { pattern: /\$\d+/g, name: "dollar sign", fix: 'Write out as "X dollars"' },
   134→    { pattern: /\d+%/g, name: "percent symbol", fix: 'Write out as "X percent"' },
   135→    { pattern: /[^\w.+\-]@[^\w]/g, name: "@ symbol", fix: 'Write out as "at"' },
   136→    { pattern: /\d+:\d{2}\s*(?:am|pm|AM|PM)/g, name: "colon in time", fix: 'Write as "one pm" not "1:00 PM"' },
   137→  ];
   138→  for (const line of agentLines) {
   139→    for (const { pattern, name, fix } of symbolPatterns) {
   140→      if (pattern.test(line)) {
   141→        issues.push({
   142→          category: "Technical Precision",
   143→          rule: `Write out symbols as words: ${name}`,
   144→          severity: "warning",
   145→          evidence: truncate(line, 200),
   146→          call_id: callId,
   147→          suggestion: fix,
   148→        });
   149→      }
   150→      pattern.lastIndex = 0; // reset regex
   151→    }
   152→  }
   153→
   154→  // ── 6. ASKING FOR SAME DATA TWICE ────────────────────────
   155→  const dataRequests = new Map<string, number>();
   156→  const dataPatterns = [
   157→    { pattern: /(?:what(?:'s| is)) your (?:first |last )?name/i, key: "name" },
   158→    { pattern: /(?:what(?:'s| is)) your (?:email|e-mail)/i, key: "email" },
   159→    { pattern: /(?:what(?:'s| is)) your (?:phone|number|cell)/i, key: "phone" },
   160→    { pattern: /(?:what(?:'s| is)) your (?:address|zip|postal)/i, key: "address" },
   161→  ];
   162→  for (const line of agentLines) {
   163→    for (const { pattern, key } of dataPatterns) {
   164→      if (pattern.test(line)) {
   165→        const count = (dataRequests.get(key) ?? 0) + 1;
   166→        dataRequests.set(key, count);
   167→        if (count > 1) {
   168→          issues.push({
   169→            category: "Call Management",
   170→            rule: "Track information provided - never ask for same data twice",
   171→            severity: "critical",
   172→            evidence: `Asked for "${key}" ${count} times`,
   173→            call_id: callId,
   174→            suggestion:
   175→              "Store provided information and reference it. Never re-ask for data already given.",
   176→          });
   177→        }
   178→      }
   179→    }
   180→  }
   181→
   182→  // ── 7. TOO MANY OPTIONS OFFERED ───────────────────────────
   183→  for (const line of agentLines) {
   184→    // Count numbered options or "or" separated items
   185→    const orCount = (line.match(/\bor\b/gi) || []).length;
   186→    const numberedOptions = line.match(/(?:^|\s)(?:1\)|2\)|3\)|4\)|first|second|third|fourth)/gi);
   187→    if (orCount >= 3 || (numberedOptions && numberedOptions.length >= 4)) {
   188→      issues.push({
   189→        category: "Call Management",
   190→        rule: "Limit choices to 3 options maximum",
   191→        severity: "warning",
   192→        evidence: truncate(line, 200),
   193→        call_id: callId,
   194→        suggestion:
   195→          "Present at most 3 options. If more exist, offer the top 3 and ask if they'd like other options.",
   196→      });
   197→    }
   198→  }
   199→
   200→  // ── 8. LONG AGENT RESPONSES ───────────────────────────────
   201→  for (const line of agentLines) {
   202→    const wordCount = line.split(/\s+/).length;
   203→    if (wordCount > 80) {
   204→      issues.push({
   205→        category: "Communication Flow",
   206→        rule: "Keep interactions brief with short sentences",
   207→        severity: "warning",
   208→        evidence: `Agent response was ${wordCount} words: "${truncate(line, 150)}"`,
   209→        call_id: callId,
   210→        suggestion:
   211→          "Break long responses into shorter segments. Aim for 1-3 sentences per turn.",
   212→      });
   213→    }
   214→  }
   215→
   216→  // ── 9. NO FILLER WORDS USED ───────────────────────────────
   217→  const fillerWords = ["umm", "um", "uh", "so,", "well,", "hmm", "let me see"];
   218→  let fillerCount = 0;
   219→  for (const line of agentLines) {
   220→    const lower = line.toLowerCase();
   221→    for (const filler of fillerWords) {
   222→      if (lower.includes(filler)) {
   223→        fillerCount++;
   224→        break;
   225→      }
   226→    }
   227→  }
   228→  if (agentLines.length > 4 && fillerCount === 0) {
   229→    issues.push({
   230→      category: "Communication Flow",
   231→      rule: "Use natural filler words for human-like conversation",
   232→      severity: "info",
   233→      evidence: `0 filler words detected across ${agentLines.length} agent turns`,
   234→      call_id: callId,
   235→      suggestion:
   236→        'Add natural fillers like "umm", "so" - minimum one every two sentences for natural flow.',
   237→    });
   238→  }
   239→
   240→  // ── 10. REPEATED TIMEZONE MENTIONS ────────────────────────
   241→  const timezonePatterns = /(?:eastern|pacific|central|mountain|ET|PT|CT|MT|EST|PST|CST|MST|EDT|PDT|CDT|MDT)\s*(?:time|timezone|standard|daylight)?/gi;
   242→  let tzMentions = 0;
   243→  for (const line of agentLines) {
   244→    const matches = line.match(timezonePatterns);
   245→    if (matches) tzMentions += matches.length;
   246→  }
   247→  if (tzMentions > 2) {
   248→    issues.push({
   249→      category: "Technical Precision",
   250→      rule: "State timezone once, don't repeat throughout call",
   251→      severity: "warning",
   252→      evidence: `Timezone mentioned ${tzMentions} times across the call`,
   253→      call_id: callId,
   254→      suggestion: "State the timezone once at the beginning and don't repeat it.",
   255→    });
   256→  }
   257→
   258→  // ── 11. MISSING UH-HUH FOR UNFINISHED MESSAGES ───────────
   259→  if (utterances) {
   260→    for (let i = 0; i < utterances.length - 1; i++) {
   261→      const curr = utterances[i];
   262→      const next = utterances[i + 1];
   263→      // Two user messages in a row (indicates broken/unfinished message)
   264→      if (
   265→        curr.role === "user" &&
   266→        next.role === "user" &&
   267→        i + 2 < utterances.length &&
   268→        utterances[i + 2].role === "agent"
   269→      ) {
   270→        const agentResponse = utterances[i + 2].content.toLowerCase();
   271→        if (!agentResponse.includes("uh-huh") && !agentResponse.includes("uh huh") && !agentResponse.includes("mhm")) {
   272→          issues.push({
   273→            category: "Technical Precision",
   274→            rule: 'Respond "uh-huh" to obviously unfinished messages',
   275→            severity: "info",
   276→            evidence: `User sent two messages in a row: "${truncate(curr.content, 80)}" then "${truncate(next.content, 80)}"`,
   277→            call_id: callId,
   278→            suggestion:
   279→              'When receiving broken/unfinished messages (2 in a row), respond with "uh-huh" to acknowledge.',
   280→          });
   281→        }
   282→      }
   283→    }
   284→  }
   285→
   286→  // ── 12. MISSING VERBAL BRIDGES FOR TOOL CALLS ────────────
   287→  // Check if agent says something like "let me check" before pauses
   288→  const bridgePhrases = [
   289→    "let me check",
   290→    "let me look",
   291→    "one moment",
   292→    "give me a sec",
   293→    "checking",
   294→    "looking into",
   295→    "pulling that up",
   296→    "let me see",
   297→    "hold on",
   298→    "bear with me",
   299→  ];
   300→  if (utterances) {
   301→    for (let i = 0; i < utterances.length - 1; i++) {
   302→      const curr = utterances[i];
   303→      const next = utterances[i + 1];
   304→      // Look for agent turns followed by long gaps (if word timing is available)
   305→      if (curr.role === "agent" && next.role === "agent" && curr.words && next.words) {
   306→        const gap = (next.words[0]?.start ?? 0) - (curr.words[curr.words.length - 1]?.end ?? 0);
   307→        if (gap > 3000) {
   308→          // 3+ second gap
   309→          const hasBridge = bridgePhrases.some((p) =>
   310→            curr.content.toLowerCase().includes(p)
   311→          );
   312→          if (!hasBridge) {
   313→            issues.push({
   314→              category: "Function Integration",
   315→              rule: "Use verbal bridges during processing",
   316→              severity: "warning",
   317→              evidence: `${(gap / 1000).toFixed(1)}s gap without verbal bridge: "${truncate(curr.content, 100)}"`,
   318→              call_id: callId,
   319→              suggestion:
   320→                'Add phrases like "Let me check that for you..." before tool calls or lookups.',
   321→            });
   322→          }
   323→        }
   324→      }
   325→    }
   326→  }
   327→
   328→  // ── 13. CALL ENDING CHECK ─────────────────────────────────
   329→  if (agentLines.length > 0) {
   330→    const lastAgentLine = agentLines[agentLines.length - 1].toLowerCase();
   331→    const goodbyePhrases = [
   332→      "goodbye",
   333→      "bye",
   334→      "take care",
   335→      "have a great",
   336→      "have a good",
   337→      "have a wonderful",
   338→      "thanks for calling",
   339→      "thank you for calling",
   340→    ];
   341→    const hasGoodbye = goodbyePhrases.some((p) => lastAgentLine.includes(p));
   342→    if (!hasGoodbye && agentLines.length > 3) {
   343→      issues.push({
   344→        category: "Call Management",
   345→        rule: "End calls cleanly after goodbye phrases",
   346→        severity: "info",
   347→        evidence: `Last agent message: "${truncate(agentLines[agentLines.length - 1], 150)}"`,
   348→        call_id: callId,
   349→        suggestion:
   350→          "Ensure the agent ends with a clear goodbye and triggers the end_call function.",
   351→      });
   352→    }
   353→  }
   354→
   355→  // ── 14. PROMPT STRUCTURE CHECK (via prompt text) ──────────
   356→  // This is checked at the prompt level, not transcript level.
   357→  // Included here as a placeholder - the actual prompt audit happens
   358→  // when Claude reads the prompt via get_agent_prompt.
   359→
   360→  return issues;
   361→}
   362→
   363→// ── Helpers ─────────────────────────────────────────────────────
   364→
   365→function extractAgentLines(transcript: string): string[] {
   366→  const lines: string[] = [];
   367→  const agentPattern = /^(?:Agent|AI|Bot|Assistant):\s*(.+)$/gim;
   368→  let match;
   369→  while ((match = agentPattern.exec(transcript)) !== null) {
   370→    lines.push(match[1]);
   371→  }
   372→  // Fallback: if no labeled lines found, try Retell's format
   373→  if (lines.length === 0) {
   374→    // Retell transcripts often don't have labels - use utterance objects instead
   375→    // This fallback splits on newlines and alternates (rough heuristic)
   376→    const allLines = transcript.split("\n").filter((l) => l.trim());
   377→    for (let i = 0; i < allLines.length; i += 2) {
   378→      if (i + 1 < allLines.length) lines.push(allLines[i + 1]);
   379→    }
   380→  }
   381→  return lines;
   382→}
   383→
   384→function extractUserLines(transcript: string): string[] {
   385→  const lines: string[] = [];
   386→  const userPattern = /^(?:User|Human|Caller|Customer):\s*(.+)$/gim;
   387→  let match;
   388→  while ((match = userPattern.exec(transcript)) !== null) {
   389→    lines.push(match[1]);
   390→  }
   391→  return lines;
   392→}
   393→
   394→function truncate(text: string, max: number): string {
   395→  return text.length > max ? text.substring(0, max) + "..." : text;
   396→}
   397→
   398→// ── Tool Registration ───────────────────────────────────────────
   399→
   400→export const registerAnalysisTools = (server: McpServer, client: Retell) => {
